def public_page(key, data):
    html = page(key, data)
    return html.replace('href="/', 'href="/lenguaje/').replace('src="/', 'src="/lenguaje/')

for key, data in DATA.items():
    target = ROOT / 'docs' / key / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(public_page(key, data), encoding='utf-8')
(ROOT / 'docs/index.html').write_text(public_page('maestria', DATA['maestria']), encoding='utf-8')
